{view==='Services'&&<><div className="toolbar"><div className="tabs">{['All',...businessTypes.map((type:{name:string;color:string})=>type.name)].map(c=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div><button className="outline" onClick={()=>setView('Settings')}>Edit catalog</button></div><div className="service-grid">{config.services.filter((s:Any)=>category==='All'||s.category===category).map((s:Any)=><article className="service-card panel" key={s.id}><span className="service-icon" style={{background:'color-mix(in srgb, '+(serviceAccent(s.name)||brandPrimary)+' 14%, var(--sf-card))',color:serviceAccent(s.name)||'var(--sf-on-card)'}}><Shapes size={24}/></span><span className="category-label">{s.category}</span><h2>{s.name}</h2><p>{s.description}</p><div className="service-bottom"><span><Clock size={15}/> {durationLabel(s)}</span><b>{cash(s.price)}</b></div><button disabled={isTermUnit(s.durationUnit||'minutes')} className="outline" onClick={()=>{startBooking();setSelected([s.id]);}}>{isTermUnit(s.durationUnit||'minutes')?'Track enrollment below':'Book this service'}</button></article>)}</div><OwnerTermTracker services={config.services}/></>}
{view==='Memberships'&&<OwnerMemberships slug={businessSlug}/>}
{view==='Checkout'&&<div className="checkout-grid"><section><div className="notice">Cash sales can be recorded manually. Card payments, deposits, discounts and refunds are not connected.</div><h2>Services</h2><div className="product-grid">{config.services.map((p:Any)=><button className="product-tile" key={p.id} onClick={()=>add(p)}><Shapes aria-hidden="true"/><b>{p.name}</b><span>{cash(p.price)}</span><Plus size={17}/></button>)}</div><h2 className="section-gap">Studio essentials</h2><div className="product-grid">{config.products.map((p:Any)=><button className="product-tile" key={p.id} onClick={()=>add(p)}><ShoppingBag/><b>{p.name}</b><span>{cash(p.price)}</span><Plus size={17}/></button>)}</div></section><section className="panel receipt"><h2>Current sale</h2><p>Cash · manually recorded</p>{!cart.length&&<div className="empty"><ShoppingBag/><p>Add a service or product to begin.</p></div>}{cart.map(p=><div className="receipt-line" key={p.id}><div><b>{p.name}</b><small>{p.qty} × {cash(p.price)}</small></div><span>{cash(p.price*p.qty)}</span><button className="icon-btn" aria-label={'Remove '+p.name} onClick={()=>setCart(c=>c.filter(x=>x.id!==p.id))}><X size={15}/></button></div>)}<div className="receipt-line"><span>Subtotal</span><b>{cash(cart.reduce((n,p)=>n+p.price*p.qty,0))}</b></div><div className="receipt-line"><span>Tax ({config.tax}%)</span><b>{cash(cart.reduce((n,p)=>n+p.price*p.qty,0)*config.tax/100)}</b></div><div className="receipt-total"><span>Total</span><b>{cash(cart.reduce((n,p)=>n+p.price*p.qty,0)*(1+config.tax/100))}</b></div><button className="primary full" disabled={!cart.length||busy} onClick={async()=>{if(!confirm('Confirm that cash was received for this sale?'))return;if(await action({action:'sale',items:cart.map(p=>({id:p.id,qty:p.qty}))})){setCart([]);await refresh();setToast('Cash sale recorded.');}}}>Record cash received</button><small>Only record money you have actually received. Inventory tracking is not enabled in this release.</small></section></div>}
{view==='Reports'&&<><OwnerTermTracker services={config.services} compact/><div className="toolbar"><div className="tabs">{['Today','This month','All time'].map(r=><button key={r} className={range===r?'active':''} onClick={()=>setRange(r)}>{r}</button>)}</div><button className="outline" onClick={download}><Download size={16}/> Export appointments</button></div><div className="stats"><Stat title="Paid revenue" value={cash(revenue)} sub="Recorded cash · excludes tax" icon={<CreditCard/>}/><Stat title="Appointments" value={reportAppointments.length} sub="Scheduled for selected period" icon={<CalendarDays/>}/><Stat title="Completed" value={reportAppointments.filter(a=>a.status==='Completed').length} sub="Completion does not imply payment" icon={<CheckCircle2/>}/><Stat title="Cancellations" value={reportAppointments.filter(a=>a.status==='Cancelled').length} sub="No refunds issued automatically" icon={<X/>}/></div><div className="two-col"><section className="panel padded"><h2>Revenue breakdown</h2>{['service','product'].map(type=><div className="report-row" key={type}><span>{type==='service'?'Service revenue':'Retail revenue'}</span><b>{cash(sales.reduce((n,e)=>n+e.lines.filter((l:Any)=>l.type===type).reduce((t:number,l:Any)=>t+l.price*l.qty,0),0))}</b></div>)}<div className="report-row"><span>Retail cost of goods sold</span><b>{cash(sales.reduce((n,e)=>n+e.lines.filter((l:Any)=>l.type==='product').reduce((t:number,l:Any)=>t+l.cost*l.qty,0),0))}</b></div><div className="notice">Gross and net profit are unavailable until service materials, direct labor, payment fees and operating expenses are recorded. Retail costs use the catalog cost at sale time.</div></section><section className="panel padded"><h2>Appointments by weekday</h2>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>{const n=reportAppointments.filter(a=>new Date(a.date+'T12:00:00').getDay()===i).length;return <div className="weekday" key={d}><span>{d}</span><div><i style={{width:(reportAppointments.length?n/reportAppointments.length*100:0)+'%'}}/></div><b>{reportAppointments.length?Math.round(n/reportAppointments.length*100):0}%</b></div>})}</section></div><section className="panel padded section-gap"><h2>Recorded transactions</h2>{sales.length?sales.map(s=><div className="report-row" key={s.id}><span>{new Date(s.created).toLocaleString('en-US',{timeZone:'America/New_York'})} · {s.lines.map((l:Any)=>l.name).join(', ')}</span><b>{cash(s.total)}</b></div>):<div className="empty">No cash sales in this period.</div>}</section></>}
{view==='Receptionist'&&<div className="two-col"><section className="panel padded"><span className="service-icon purple"><Sparkles/></span><h2>Your digital welcome desk</h2><p className="muted">A guided assistant grounded in your studio’s service catalog, hours and cancellation policy.</p><div className="report-row"><span>FAQ assistant</span><span className="status confirmed">Ready to try</span></div>{['Generative AI','SMS & WhatsApp','Phone receptionist','Email reminders'].map(n=><div className="report-row" key={n}><span>{n}</span><span className="muted">Not connected</span></div>)}<button className="primary section-gap" onClick={()=>setChat(true)}><MessageCircle size={18}/> Test assistant</button><p className="muted">The assistant cannot charge customers or modify appointments. Booking always requires confirmation in the booking form.</p></section><section className="panel padded"><h2>Human handoff inbox</h2><p className="muted">Requests saved by the assistant. Notifications are not enabled.</p>{events.filter(e=>e.kind==='handoff').map(e=><div className="handoff" key={e.id}><span className="status confirmed">Open</span><p>{e.message}</p><small>{new Date(e.created).toLocaleString()}</small></div>)}{!events.some(e=>e.kind==='handoff')&&<div className="empty"><CheckCircle2/><h3>All quiet here.</h3><p>Client requests for a human will appear here.</p></div>}</section></div>}
